{"path": "/tmp/sv-b493c8f9ba9e46fc93fee7c0fa40a555/scripts/install-sdk.ps1", "file_text": "<#
.SYNOPSIS
    Installs the .NET SDK version specified in global.json into a local .dotnet directory.
#>
[CmdletBinding()]
param (
    [string]$InstallDir
)

$ErrorActionPreference = 'Stop'

$repoRoot = Split-Path -Parent (Split-Path -Parent $MyInvocation.MyCommand.Definition)
if (-not $InstallDir) {
    $InstallDir = Join-Path $repoRoot '.dotnet'
}

$globalJson = Get-Content (Join-Path $repoRoot 'global.json') -Raw | ConvertFrom-Json
$sdkVersion = $globalJson.sdk.version

Write-Host "Installing .NET SDK $sdkVersion to $InstallDir ..."

$installScript = Join-Path $repoRoot 'scripts' '.dotnet-install.ps1'
try {
    Invoke-WebRequest -Uri 'https://dot.net/v1/dotnet-install.ps1' -OutFile $installScript -UseBasicParsing

    & $installScript -Version $sdkVersion -InstallDir $InstallDir -NoPath
}
finally {
    if (Test-Path $installScript) { Remove-Item $installScript -Force }
}

Write-Host ''
Write-Host 'SDK installed. Set the following environment variables before building:'
Write-Host ''
Write-Host "  `$env:DOTNET_ROOT = '$InstallDir'"
Write-Host "  `$env:PATH        = '$InstallDir;' + `$env:PATH"
"}

